mapper.select:
select 

from MST_SHARE_PRICE
where SHARES_ID = #{sharesId,jdbcType=VARCHAR}
	and  deal_date= (select max(deal_date) from mst_share_price 
  						where to_char(DEAL_DATE,'yyyy-MM-dd') < #{dealDateString}
  						and SHARES_ID = #{sharesId,jdbcType=VARCHAR})

select distinct a.SHARES_ID SHARES_ID, a.DEAL_DATE DEAL_DATE, a.CCY CCY, a.PRE_CLOSE_PRICE PRE_CLOSE_PRICE, a.OPEN_PRICE OPEN_PRICE, a.HIGH_PRICE HIGH_PRICE, a.LOW_PRICE LOW_PRICE, a.CLOSE_PRICE CLOSE_PRICE, a.S_SHARES S_SHARES, a.C_SHARES C_SHARES, a.CHANGE CHANGE, a.CHANGE_PERCENT CHANGE_PERCENT, a.DEAL_VALUME DEAL_VALUME, a.DEAL_AMOUNT DEAL_AMOUNT, a.AVG_PRICE AVG_PRICE, a.PRE_CLOSE_PRICE_ADJ PRE_CLOSE_PRICE_ADJ, a.OPEN_PRICE_ADJ OPEN_PRICE_ADJ, a.HIGH_PRICE_ADJ HIGH_PRICE_ADJ, a.LOW_PRICE_ADJ LOW_PRICE_ADJ, a.CLOSE_PRICE_ADJ CLOSE_PRICE_ADJ, a.FACTOR_ADJ FACTOR_ADJ, a.TRADE_STATUS TRADE_STATUS, a.INPUT_TYPE INPUT_TYPE, a.CREATE_USER CREATE_USER, a.CREATE_DEPT CREATE_DEPT, a.CREATE_TIME CREATE_TIME, a.UPDATE_USER UPDATE_USER, a.UPDATE_TIME UPDATE_TIME, b.finprod_abbr finprod_abbr from mst_share_price a left join fin_product b on a.shares_id=b.finprod_market_id
and SHARES_ID =#{sharesId}
and to_char(DEAL_DATE,'yyyy-MM-dd') =#{dealDateString}
